            }
        }

        /* ===========================================
           ANIMATIONS
           Trigger via .visible class (added by JS on scroll)
           =========================================== */
        .reveal {
            opacity: 0;
            transform: translateY(30px);
            transition: opacity var(--duration-normal) var(--ease-out-expo),
                        transform var(--duration-normal) var(--ease-out-expo);
        }
        .slide.visible .reveal {
            opacity: 1;
            transform: translateY(0);
        }
        .reveal:nth-child(1) { transition-delay: 0.1s; }
        .reveal:nth-child(2) { transition-delay: 0.2s; }
        .reveal:nth-child(3) { transition-delay: 0.3s; }
        .reveal:nth-child(4) { transition-delay: 0.4s; }
        .reveal:nth-child(5) { transition-delay: 0.5s; }
        .reveal:nth-child(6) { transition-delay: 0.6s; }

        /* ===========================================
           NEON CYBER THEME STYLES
           =========================================== */
        body {
            font-family: var(--font-body);
            background: var(--bg-primary);
            color: var(--text-primary);
        }

        /* Slide backgrounds with gradient mesh */
        .slide {
            background:
                radial-gradient(ellipse at 20% 80%, rgba(0, 255, 204, 0.08) 0%, transparent 50%),
                radial-gradient(ellipse at 80% 20%, rgba(255, 0, 170, 0.05) 0%, transparent 50%),
                var(--bg-primary);
        }

        /* Grid overlay for tech feel */
        .slide::before {
            content: '';
            position: absolute;
            inset: 0;
            background-image:
                linear-gradient(rgba(0, 255, 204, 0.03) 1px, transparent 1px),
                linear-gradient(90deg, rgba(0, 255, 204, 0.03) 1px, transparent 1px);
            background-size: 40px 40px;
            pointer-events: none;
        }

        /* Title Slide specific */
        .title-slide {
            justify-content: center;
            align-items: center;
            text-align: center;
        }
        .title-slide h1 {
            font-family: var(--font-display);
            font-size: var(--title-size);
            font-weight: 700;
            background: linear-gradient(135deg, var(--accent-cyan), var(--accent-magenta));
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            background-clip: text;
            margin-bottom: var(--content-gap);
            text-shadow: 0 0 60px var(--glow-cyan);
        }
        .title-slide .subtitle {
            font-size: var(--h3-size);
            color: var(--text-secondary);
            margin-bottom: var(--element-gap);
        }
        .title-slide .meta {
            display: flex;
            gap: clamp(1rem, 3vw, 3rem);
            justify-content: center;
            flex-wrap: wrap;
            margin-top: var(--content-gap);
        }
        .title-slide .meta-item {
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 0.25rem;
        }
        .title-slide .meta-value {
            font-size: var(--h3-size);
            font-weight: 700;
            color: var(--accent-cyan);
        }
        .title-slide .meta-label {
            font-size: var(--small-size);
            color: var(--text-secondary);
            text-transform: uppercase;
            letter-spacing: 0.1em;
        }

        /* Content slides */
        .slide h2 {
            font-family: var(--font-display);
            font-size: var(--h2-size);
            font-weight: 600;
            color: var(--text-primary);
            margin-bottom: var(--content-gap);
        }
        .slide h2 .highlight {
            color: var(--accent-cyan);
        }
        .slide h3 {
            font-size: var(--h3-size);
            font-weight: 500;
            color: var(--text-secondary);
            margin-bottom: var(--element-gap);
        }

        /* Metric cards */
        .metric-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(min(100%, 180px), 1fr));
            gap: clamp(0.75rem, 2vw, 1.5rem);
            margin: var(--content-gap) 0;
        }
        .metric-card {
            background: var(--bg-card);
            border: 1px solid rgba(0, 255, 204, 0.2);
            border-radius: 12px;
            padding: clamp(1rem, 2vw, 1.5rem);
            text-align: center;
            position: relative;
            overflow: hidden;
        }
        .metric-card::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            right: 0;
            height: 3px;
            background: linear-gradient(90deg, var(--accent-cyan), var(--accent-magenta));
        }
        .metric-card .value {
            font-family: var(--font-display);
            font-size: var(--metric-size);
            font-weight: 700;
            color: var(--accent-cyan);
            line-height: 1;
        }
        .metric-card .value.orange { color: var(--accent-orange); }
        .metric-card .value.green { color: var(--accent-green); }
        .metric-card .value.red { color: var(--accent-red); }
        .metric-card .label {
            font-size: var(--small-size);
            color: var(--text-secondary);
            text-transform: uppercase;
            letter-spacing: 0.05em;
            margin-top: 0.5rem;
        }

        /* Chart containers */
        .chart-container {
            background: var(--bg-card);
            border: 1px solid rgba(0, 255, 204, 0.15);
            border-radius: 16px;
            padding: clamp(1rem, 3vw, 2rem);
            margin: var(--content-gap) 0;
        }
        .chart-title {
            font-size: var(--small-size);
            color: var(--text-secondary);
            text-transform: uppercase;
            letter-spacing: 0.1em;
            margin-bottom: var(--element-gap);
        }

        /* Bar chart styles */
        .bar-chart {
            display: flex;
            align-items: flex-end;
            justify-content: center;
            gap: clamp(1rem, 3vw, 3rem);
            height: min(40vh, 300px);
            padding: var(--element-gap) 0;
        }
        .bar-item {
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 0.5rem;
            flex: 1;
            max-width: 150px;
        }
        .bar {
            width: 100%;
            border-radius: 8px 8px 0 0;
            position: relative;
            transition: height 0.8s var(--ease-out-expo);
        }
        .bar.issuance {
            background: linear-gradient(180deg, var(--accent-orange), #ff8c5a);
            box-shadow: 0 0 20px rgba(255, 107, 53, 0.4);
        }
        .bar.burn {
            background: linear-gradient(180deg, var(--accent-green), #5effa0);
            box-shadow: 0 0 20px rgba(0, 255, 136, 0.4);
        }
        .bar-value {
            position: absolute;
            top: -2rem;
            left: 50%;
            transform: translateX(-50%);
            font-size: var(--small-size);
            font-weight: 700;
            white-space: nowrap;
        }
        .bar-label {
            font-size: var(--small-size);
            color: var(--text-secondary);
            text-align: center;
        }

        /* Line chart for projections */
        .line-chart {
            position: relative;
            height: min(35vh, 280px);
            border-left: 2px solid rgba(0, 255, 204, 0.3);
            border-bottom: 2px solid rgba(0, 255, 204, 0.3);
            margin: var(--content-gap) var(--element-gap);
        }
        .line-chart svg {
            width: 100%;
            height: 100%;
        }
        .chart-axis-label {
            font-size: clamp(0.5rem, 0.8vw, 0.7rem);
            fill: var(--text-secondary);
        }
        .chart-line {
            fill: none;
            stroke: var(--accent-cyan);
            stroke-width: 2;
            stroke-linecap: round;
        }
        .chart-area {
            fill: url(#cyanGradient);
            opacity: 0.3;
        }
        .chart-dot {
            fill: var(--accent-cyan);
        }

        /* Horizontal bar chart for categories */
        .h-bar-chart {
            display: flex;
            flex-direction: column;
            gap: clamp(0.5rem, 1.5vw, 1rem);
        }
        .h-bar-item {
            display: grid;
            grid-template-columns: 100px 1fr 60px;
            align-items: center;
            gap: 1rem;
        }
        .h-bar-label {
            font-size: var(--small-size);
            color: var(--text-secondary);
            text-align: right;
        }
        .h-bar-track {
            height: 24px;
            background: var(--bg-secondary);
            border-radius: 12px;
            overflow: hidden;
        }
        .h-bar-fill {
            height: 100%;
            border-radius: 12px;
            transition: width 0.8s var(--ease-out-expo);
        }
        .h-bar-fill.defi { background: linear-gradient(90deg, var(--accent-blue), #6b83f2); }
