            font-size: var(--h3-size);
            font-weight: 700;
            color: var(--accent-cyan);
        }
        .staking-item .label {
            font-size: var(--small-size);
            color: var(--text-secondary);
        }

        /* Flippening metrics */
        .flippening-grid {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: clamp(0.75rem, 2vw, 1.5rem);
            margin-bottom: var(--content-gap);
