    const outDir = '/tmp/slide_debug';
    if (!fs.existsSync(outDir)) fs.mkdirSync(outDir, { recursive: true });

    const server = http.createServer((req, res) => {
        const filePath = path.join('/app/output', 'presentation.html');
        const content = fs.readFileSync(filePath, 'utf8');
        res.writeHead(200, { 'Content-Type': 'text/html' });
        res.end(content);
    });
    await new Promise(resolve => server.listen(9876, () => console.log('Server on 9876')));

    const browser = await chromium.launch();
    const page = await browser.newPage();
    await page.setViewportSize({ width: 1920, height: 1080 });
    await page.goto('http://127.0.0.1:9876/presentation.html', { waitUntil: 'networkidle' });
    await page.waitForTimeout(800);

    // Count slides
    let slideCount = 0;
    const selectors = [".slide", "[data-slide]", "section", "div > section"];
    for (const sel of selectors) {
        slideCount = await page.$$eval(sel, els => els.length);
        if (slideCount > 0) break;
    }
    console.log('Detected slideCount:', slideCount);

    // Capture slide 1
    await page.screenshot({ path: `${outDir}/slide_001.png` });
    console.log('Captured slide 1');

    // Navigate and capture remaining
    for (let i = 2; i <= slideCount; i++) {
        await page.keyboard.press('ArrowRight');
        await page.waitForTimeout(700);
        const idx = String(i).padStart(3, '0');
        await page.screenshot({ path: `${outDir}/slide_${idx}.png` });
        console.log('Captured slide ' + i);
    }

    await browser.close();
    server.close();

    // List captured files
    const files = fs.readdirSync(outDir).filter(f => f.endsWith('.png')).sort();
    console.log('Files:', files.length, files);
})();
